#include <stdio.h>

int can_add(int count) {
    FILE *f = fopen("max_items.txt", "r");
    if (!f) return 0;
    int limit = 0;
    if (fscanf(f, "%d", &limit) != 1) limit = 0;
    fclose(f);
    return count <= limit;
}
